from pathlib import Path
import json,html,re,argparse
parser=argparse.ArgumentParser();parser.add_argument('--repo',default='C:/Users/Dainius/Desktop/BesiegedInConstantinopole-codex-prototype-first-playtest');args=parser.parse_args()
root=Path(__file__).resolve().parents[1] if Path(__file__).parent.name=='scripts' else Path('event-map')
repo=Path(args.repo);d=json.loads((repo/'Assets/Resources/Court/court-conversations.json').read_text(encoding='utf-8'))
script=repo/'Assets/Scripts'
def strings(s):return [json.loads(x) for x in re.findall(r'"(?:[^"\\]|\\.)*"',s)]
def array(source,name):return strings(re.search(name+r'=\{(.*?)\};',source,re.S).group(1))
garden=(script/'GardenConversations.cs').read_text(encoding='utf-8-sig');writing=(script/'CourtCharacterWriting.cs').read_text(encoding='utf-8-sig');questions=(script/'CharacterQuestions.cs').read_text(encoding='utf-8-sig')
personal=array(garden,r'string\[\] words');visitors=array(garden,'VisitorPersonal');arrival=array(writing,'ArrivalWords');city=array(writing,'CityWords');bonds=array(writing,'BondWords')
for c in d['characters']:
 p=c['person'];i=14 if p==200 else p-92 if p>=100 else p
 own=personal[p] if p<8 else visitors[p-100] if p>=100 and p<200 else strings(re.search(r'if\(person==Kjold\)return (.*?);',garden).group(1))[0]
 match=re.search(r'\['+str(p)+r'\]=new Exchange\((.*?)(?=\n        \[|\n    \};)',questions,re.S);parts=strings(match.group(1)) if match else [];assert len(parts)==7,(p,len(parts))
 c['topics']=[dict(title='Tell me about yourself',text=own),dict(title='How did you come to Constantinople?',text=arrival[i]),dict(title='What does this City mean to you? · Charisma 4',text=city[i]),dict(title='Whose judgement do you trust?',text=bonds[i]),dict(title='What do you make of the siege?',text='Dynamic: GardenConversations.Siege reads the current operation and chooses a report-specific assessment. Refreshed each turn; no XP.'),dict(title='What should I attend to?',text='Dynamic: GardenConversations.Advice selects advice about current needs. Refreshed each turn; no XP.'),dict(title='Was there something you wished to ask me?',text=parts[0] if parts else '',replies=parts[1:4],responses=parts[4:7])]

context=(script/'SiegeCharacterContext.cs').read_text(encoding='utf-8-sig')
for c in d['characters']:
 c['topics'].append(dict(title='How is your part of the defence holding?',text='Dynamic: SiegeCharacterContext.Text responds to preparation, opening siege, prolonged siege, chain status, actual sea control, current wall integrity, ammunition, or Union and Papal aid state, according to the speaker.'))
 if c['person']==5:
  for key,title in [('CannonTheory','How many cannons does a city really need?'),('CannonAnswer','Finally, do you think we have enough cannons now? · hidden threshold')]:
   text=strings(re.search(key+r'=>(.*?);',context,re.S).group(1))[0]
   c['topics'].append(dict(title=title,text=text))

template=r'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Besieged · Conversations and quests</title><style>
*{box-sizing:border-box}body{margin:0;background:#09131d;color:#e6dcc0;font:15px Georgia,serif}header{height:110px;padding:16px 22px;border-bottom:1px solid #826a39;background:#111f2b}h2{margin:0 0 10px;color:#e8c77b}select,input,button,textarea{background:#172938;color:#e6dcc0;border:1px solid #61717d;padding:8px;font:inherit}header label{margin-left:12px}main{display:grid;grid-template-columns:minmax(0,1fr) 340px;height:calc(100vh - 110px)}aside{padding:20px;overflow:auto;border-left:1px solid #806636}aside h3{color:#e8c77b}aside p{line-height:1.5}.graph{overflow:hidden;position:relative}svg{width:100%;height:100%;cursor:grab;touch-action:none}.help{position:absolute;bottom:8px;left:16px;color:#a9b5bd;background:#09131dcc;padding:8px}textarea{width:100%;min-height:100px}.meta{color:#aabcc5;font:13px sans-serif}.key{font:13px sans-serif}button{cursor:pointer}.selected rect{stroke:#fff0be;stroke-width:3}foreignObject{pointer-events:none}.node-label{font:15px Georgia;color:#e8dfc6;padding:10px}.node-label small{font:12px sans-serif;color:#a9bccb;display:block;margin-bottom:6px}.node{cursor:pointer}.legend{margin-top:8px;font:12px sans-serif}.legend span{margin-right:16px}
</style><header><h2>Conversations &amp; character quests</h2><select id="person"><option value="all">All fifteen court characters</option></select> <input id="search" placeholder="Search scenes, choices, secrets…"><button id="fit">Fit</button><label><input type="checkbox" id="links" checked>Cross-court links</label><div class="legend"><span style="color:#efba4f">● Charisma</span><span style="color:#5ca3ef">● Intellect</span><span style="color:#e0574c">● Martial skill</span>Solid arrows: quest sequence. Dotted grey: menu navigation, not a prerequisite. Dashed arrows: another character’s disclosure lowers the final requirement from 7 to 5.</div></header><main><div class="graph"><svg id="graph"><defs><marker id="arrow" markerWidth="10" markerHeight="8" refX="9" refY="4" orient="auto"><path d="M0,0L10,4L0,8" fill="#ae9253"/></marker></defs><g id="scene"></g></svg><div class="help">Wheel to zoom · drag empty space to pan · click a scene to inspect</div></div><aside id="details"><h3>Runtime source: Unity court catalogue</h3><p>Fifteen fictional character quests, three stages each. Choices, requirements, shared information and ending recollections are imported from the same structured JSON used by the game.</p><p>Each stage records one decision. Later scenes wait one or two calendar days. Decisions award 15, 30 and 60 XP respectively, once. Rereading awards nothing.</p><p>These conversations make arrangements and record consequences; they do not themselves create ships, transfer troops or resolve the separate murder investigation.</p></aside></main><script id="catalogue" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('catalogue').textContent),$=s=>document.querySelector(s),scene=$('#scene'),svg=$('#graph');const colours=['#efba4f','#5ca3ef','#e0574c'],stats=['Charisma','Intellect','Martial skill'];let scale=1,px=30,py=20,drag=null,shown=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const c of data.characters)$('#person').insertAdjacentHTML('beforeend',`<option value="${c.person}">${esc(c.name)}</option>`);
function transform(){scene.setAttribute('transform',`translate(${px},${py}) scale(${scale})`)}
function render(){let query=$('#search').value.toLowerCase(),person=$('#person').value;shown=data.characters.filter(c=>(person==='all'||c.person==person)&&(!query||JSON.stringify(c).toLowerCase().includes(query)));let out='',pos=new Map();shown.forEach((c,row)=>{pos.set('conversation.'+c.person,{x:30,y:25+row*150,c,s:{title:'Conversations · '+c.topics.length+' topics'},i:-1});c.stages.forEach((s,i)=>pos.set(s.id,{x:380+i*350,y:25+row*150,c,s,i}));});
for(const c of shown){let core=pos.get('conversation.'+c.person),first=pos.get(c.stages[0].id);out+=`<path d="M${core.x+300},${core.y+52}H${first.x}" stroke="#657582" stroke-dasharray="2 5" fill="none"/>`;for(let i=0;i<2;i++){let a=pos.get(c.stages[i].id),b=pos.get(c.stages[i+1].id);out+=`<path d="M${a.x+300},${a.y+52}H${b.x}" stroke="#ae9253" fill="none" marker-end="url(#arrow)"/>`}if($('#links').checked){let peer=data.characters.find(p=>p.person===c.link),a=peer&&pos.get(peer.stages[1].id),b=pos.get(c.stages[2].id);if(a&&b)out+=`<path d="M${a.x+300},${a.y+75}C${a.x+335},${a.y+75} ${b.x-35},${b.y+80} ${b.x},${b.y+80}" stroke="#4f9eac" stroke-dasharray="5 6" opacity=".65" fill="none" marker-end="url(#arrow)"/>`}}
for(const [id,p]of pos){out+=`<g class="node" data-id="${id}" transform="translate(${p.x},${p.y})"><rect width="300" height="110" rx="7" fill="#142430" stroke="${colours[p.c.stat]}"/><foreignObject width="300" height="110"><div xmlns="http://www.w3.org/1999/xhtml" class="node-label"><small>${esc(p.c.name)} · ${p.i<0?'TOPICS':(p.i+1)+'/3'}${p.s.minStat?' · '+stats[p.c.stat]+' '+p.s.minStat:''}</small>${esc(p.s.title)}</div></foreignObject></g>`}scene.innerHTML=out;scene.querySelectorAll('.node').forEach(n=>n.onclick=()=>inspect(n.dataset.id));fit()}
function fit(){let h=Math.max(140,shown.length*150+30),w=1400;scale=Math.min((svg.clientWidth-35)/w,(svg.clientHeight-35)/h);px=18;py=18;transform()}
function inspect(id){if(id.startsWith('conversation.')){let c=data.characters.find(c=>'conversation.'+c.person===id);$('#details').innerHTML='<h3>'+esc(c.name)+' · conversation topics</h3>'+c.topics.map(t=>'<details open><summary>'+esc(t.title)+'</summary><p>'+esc(t.text)+'</p>'+((t.replies||[]).map((r,i)=>'<p><b>'+esc(r)+'</b><br>'+esc(t.responses[i])+'</p>').join(''))+'</details>').join('')+'<p class="meta">Read flags persist per topic. Biography requires no stat; the City question unlocks at Charisma 4. The personal question allows one reply and grants 15 Charisma XP once. Instruction grants 25 XP and spends a major action.</p>';return;}let c=data.characters.find(c=>c.stages.some(s=>s.id===id)),s=c.stages.find(s=>s.id===id),i=c.stages.indexOf(s),peer=data.characters.find(p=>p.person===c.link);scene.querySelectorAll('.node').forEach(n=>n.classList.toggle('selected',n.dataset.id===id));$('#details').innerHTML=`<div class="meta">${esc(id)} · IMPLEMENTED FICTION</div><h3>${esc(c.name)}<br>${esc(s.title)}</h3><p>${esc(s.text)}</p><p style="color:${colours[c.stat]}">${s.minStat?stats[c.stat]+' '+s.minStat:'No attribute requirement'}${i===2?' · or 5 after '+esc(peer.name)+'’s disclosure':''}${s.delayDays?' · '+s.delayDays+' days after the previous choice':''}</p><h3>A · ${esc(s.choiceA)}</h3><p>${esc(s.responseA)}</p><h3>B · ${esc(s.choiceB)}</h3><p>${esc(s.responseB)}</p><p class="meta">One-time ${[15,30,60][i]} ${stats[c.stat]} XP. Choice and date persist in the campaign save. Final arrangement is recalled in the epilogue.</p><h3>Review notes</h3><textarea id="note"></textarea><p class="meta">Notes stay in this browser; game source is unchanged.</p>`;const key='besieged-conversation-review:'+id;$('#note').value=localStorage.getItem(key)||'';$('#note').oninput=e=>localStorage.setItem(key,e.target.value)}
$('#person').onchange=render;$('#search').oninput=render;$('#links').onchange=render;$('#fit').onclick=fit;svg.onwheel=e=>{e.preventDefault();const r=svg.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,n=Math.min(3,Math.max(.08,scale*(e.deltaY<0?1.12:1/1.12)));px=x-(x-px)*n/scale;py=y-(y-py)*n/scale;scale=n;transform()};svg.onpointerdown=e=>{if(e.target.closest('.node'))return;drag={x:e.clientX-px,y:e.clientY-py};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(drag){px=e.clientX-drag.x;py=e.clientY-drag.y;transform()}};svg.onpointerup=()=>drag=null;render();
</script></html>'''
content=template.replace('__DATA__',json.dumps(d,ensure_ascii=False).replace('</','<\\/'))
(root/'dist/Conversation Map.html').write_text(content,encoding='utf-8')
index=root/'dist/index.html';s=index.read_text(encoding='utf-8')
button='<button data-view="conversations">Conversations &amp; quests</button>'
if button not in s:s=s.replace('<button data-view="table">',button+'<button data-view="table">')
start=s.find('<section id="conversations-view"')
if start>=0:
 end=s.index('</section>',start)+len('</section>');s=s[:start]+s[end:]
s=s.replace('<div id="content">','<div id="content"><section id="conversations-view" hidden style="height:100%;min-height:650px"><iframe title="Conversation and quest dependency map" style="border:0;width:100%;height:100%;min-height:650px" srcdoc="'+html.escape(content,quote=True)+'"></iframe></section>')
index.write_text(s,encoding='utf-8')
app=root/'dist/app.js';s=app.read_text(encoding='utf-8');s=s.replace("['map','table','checks','sources','plan','diplomacy']","['map','table','checks','sources','plan','diplomacy','conversations']");app.write_text(s,encoding='utf-8')
